  `mrp` decimal(18,2) NOT NULL,
  `sb_rate` decimal(18,2) NOT NULL,
  `ss_rate` decimal(18,2) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `alternate_unit_id` bigint(20) DEFAULT NULL,
  `base_unit_id` bigint(20) NOT NULL,
  `stock_category_id` bigint(20) DEFAULT NULL,
  `stock_group_id` bigint(20) NOT NULL,
  `maintain_warehouse` tinyint(1) NOT NULL DEFAULT 0,
