  `image` varchar(100) DEFAULT NULL,
  `has_bom` tinyint(1) NOT NULL,
  `item_code` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
