  KEY `inventory_app_stocki_alternate_unit_id_0111d13c_fk_inventory` (`alternate_unit_id`),
  KEY `inventory_app_stocki_base_unit_id_1459542b_fk_inventory` (`base_unit_id`),
  KEY `inventory_app_stocki_stock_category_id_ebc0a50e_fk_inventory` (`stock_category_id`),
  KEY `inventory_app_stocki_stock_group_id_dd949f91_fk_inventory` (`stock_group_id`),
  KEY `fk_stockitem_warehouse` (`warehouse_id`),
  CONSTRAINT `fk_stockitem_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `settings_app_warehouse` (`id`),
  CONSTRAINT `inventory_app_stocki_alternate_unit_id_0111d13c_fk_inventory` FOREIGN KEY (`alternate_unit_id`) REFERENCES `inventory_app_unit` (`id`),
  CONSTRAINT `inventory_app_stocki_base_unit_id_1459542b_fk_inventory` FOREIGN KEY (`base_unit_id`) REFERENCES `inventory_app_unit` (`id`),
  CONSTRAINT `inventory_app_stocki_stock_category_id_ebc0a50e_fk_inventory` FOREIGN KEY (`stock_category_id`) REFERENCES `inventory_app_stockcategory` (`id`),
  CONSTRAINT `inventory_app_stocki_stock_group_id_dd949f91_fk_inventory` FOREIGN KEY (`stock_group_id`) REFERENCES `inventory_app_stockgroup` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=327 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
