  `warehouse_id` bigint(20) DEFAULT NULL,
  `manufacture_date` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `inventory_app_stockt_item_id_dd019eff_fk_inventory` (`item_id`),
  KEY `inventory_app_stockt_verified_by_id_3348fc84_fk_register_` (`verified_by_id`),
