CREATE TABLE `purchase_app_purchaseorder` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_type` varchar(50) DEFAULT NULL,
  `po_no` varchar(50) NOT NULL,
  `entry_date` date NOT NULL,
  `gst_amount_1` decimal(12,2) NOT NULL,
  `gst_amount_2` decimal(12,2) NOT NULL,
  `total_amount` decimal(15,2) NOT NULL,
  `narration` longtext DEFAULT NULL,
  `other_reference` varchar(200) DEFAULT NULL,
  `terms_of_delivery` varchar(200) DEFAULT NULL,
  `dispatch_through` varchar(200) DEFAULT NULL,
  `document_no` varchar(200) DEFAULT NULL,
  `document_date` date DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `edited_by_id` bigint(20) DEFAULT NULL,
  `gst_ledger_1_id` bigint(20) DEFAULT NULL,
  `gst_ledger_2_id` bigint(20) DEFAULT NULL,
  `supplier_ledger_id` bigint(20) DEFAULT NULL,
  `purchase_ledger_id` bigint(20) DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `is_posted` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `po_no` (`po_no`),
  KEY `purchase_app_purchas_created_by_id_ffa3c3ad_fk_register_` (`created_by_id`),
  KEY `purchase_app_purchas_edited_by_id_f6670752_fk_register_` (`edited_by_id`),
  KEY `purchase_app_purchas_gst_ledger_1_id_1381babb_fk_finance_a` (`gst_ledger_1_id`),
  KEY `purchase_app_purchas_gst_ledger_2_id_20af262f_fk_finance_a` (`gst_ledger_2_id`),
  KEY `purchase_app_purchas_supplier_ledger_id_a01a917e_fk_finance_a` (`supplier_ledger_id`),
  KEY `purchase_app_purchas_purchase_ledger_id_1e2fbe84_fk_finance_a` (`purchase_ledger_id`),
  CONSTRAINT `purchase_app_purchas_purchase_ledger_id_1e2fbe84_fk_finance_a` FOREIGN KEY (`purchase_ledger_id`) REFERENCES `finance_app_ledger` (`id`)
