DROP TABLE IF EXISTS `sales_app_salesorder`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sales_app_salesorder` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_type` varchar(100) DEFAULT NULL,
  `so_no` varchar(50) NOT NULL,
  `entry_date` date NOT NULL,
  `gst_amount_1` decimal(12,2) NOT NULL,
  `gst_amount_2` decimal(12,2) NOT NULL,
  `total_amount` decimal(15,2) NOT NULL,
  `narration` longtext DEFAULT NULL,
  `is_posted` tinyint(1) NOT NULL,
  `other_reference` varchar(200) DEFAULT NULL,
  `terms_of_delivery` varchar(200) DEFAULT NULL,
  `dispatch_through` varchar(200) DEFAULT NULL,
  `document_no` varchar(200) DEFAULT NULL,
  `document_date` date DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `priority` varchar(20) NOT NULL,
  `preferred_delivery_date` datetime(6) DEFAULT NULL,
  `delivery_location_id` bigint(20) DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `customer_ledger_id` bigint(20) DEFAULT NULL,
  `edited_by_id` bigint(20) DEFAULT NULL,
  `gst_ledger_1_id` bigint(20) DEFAULT NULL,
  `gst_ledger_2_id` bigint(20) DEFAULT NULL,
  `driver_id` bigint(20) DEFAULT NULL,
  `is_synced` tinyint(1) NOT NULL,
  `sync_status` varchar(20) NOT NULL,
  `trip_id` bigint(20) DEFAULT NULL,
  `approval_status` varchar(20) NOT NULL,
  `sales_ledger_id` bigint(20) DEFAULT NULL,
  `delivery_location` varchar(255) DEFAULT NULL,
  `invoice_status` varchar(20) NOT NULL,
  `vehicle_id` bigint(20) DEFAULT NULL,
  `tally_guid` varchar(128) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `so_no` (`so_no`),
  KEY `sales_app_salesorder_created_by_id_908eafbd_fk_register_` (`created_by_id`),
  KEY `sales_app_salesorder_edited_by_id_3a108f68_fk_register_` (`edited_by_id`),
  KEY `sales_app_salesorder_customer_ledger_id_d47475e5_fk_finance_a` (`customer_ledger_id`),
  KEY `sales_app_salesorder_gst_ledger_1_id_1d51ba2b_fk_finance_a` (`gst_ledger_1_id`),
  KEY `sales_app_salesorder_gst_ledger_2_id_f1992e90_fk_finance_a` (`gst_ledger_2_id`),
  KEY `sales_app_salesorder_driver_id_35584c9b_fk_logistics` (`driver_id`),
  KEY `sales_app_salesorder_trip_id_3c62b8ef_fk_logistics` (`trip_id`),
  KEY `sales_app_salesorder_sales_ledger_id_fda23757_fk_finance_a` (`sales_ledger_id`),
  KEY `sales_app_salesorder_delivery_location_id_449db4f5` (`delivery_location_id`),
  KEY `sales_app_salesorder_vehicle_id_60567754_fk_logistics` (`vehicle_id`),
  CONSTRAINT `fk_salesorder_delivery_location` FOREIGN KEY (`delivery_location_id`) REFERENCES `logistics_app_routestopmaster` (`id`) ON DELETE SET NULL,
  CONSTRAINT `sales_app_salesorder_sales_ledger_id_fda23757_fk_finance_a` FOREIGN KEY (`sales_ledger_id`) REFERENCES `finance_app_ledger` (`id`),
  CONSTRAINT `sales_app_salesorder_vehicle_id_60567754_fk_logistics` FOREIGN KEY (`vehicle_id`) REFERENCES `logistics_app_vehicle` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=111 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
